function bind(id,action,transform=x=>x,after=null){const node=document.getElementById(id);if(!node)return;node.onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(node));node.querySelectorAll('input[type=number]').forEach(i=>{if(i.name)data[i.name]=i.value===''?null:Number(i.value);});const button=node.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{const result=await command(action,transform(data));notify(result?.message??'Saved.');after?.(result);await refresh(true);}catch(e){notify(e.message);}finally{if(button)button.disabled=false;}};}
