export async function openOperations(root,apiCall,notifyCall,userState,settingsCallback){if(account?.company.id!==userState.company.id||account?.user.id!==userState.user.id){view='HOME';selected=null;selectedWorker=null;containerPage=0;componentTab='ALL';stockTab='REGISTER';intakeTab=null;intakeSearch='';layoutDraft=null;layoutCheck=null;shapeEditor?.destroy();shapeEditor=null;turnInfo=new Map();turnBusy=new Set();turnHover=null;loadBusy=new Set();loadPick=new Map();gridSearch={};pinnedSite=null;heldSite=null;overviewSearch='';siteSearch='';openRows=new Set();skillsOpen=new Set();jobDraft={};crewFilter='All';returnView=null;schedWeek=null;schedOpen.clear();schedDraft.clear();schedX=null;}app=root;watchStyles(root);api=apiCall;notify=notifyCall;account=userState;settings=settingsCallback;stopOperations();bindGlobals();live=true;await refresh(true);schedulePoll();}
