const restoreFocus=focus=>{if(focus&&document.activeElement===document.body){if(focus.tile){const t=document.querySelector('.stockpile button[data-tile="'+focus.tile+'"]');if(t&&!t.disabled&&!t.hidden)t.focus({preventScroll:true});}else if(focus.id){const i=document.getElementById(focus.id);if(i){i.focus({preventScroll:true});try{i.setSelectionRange(focus.start,focus.end);}catch{}}}else document.querySelector('[data-focus-scope="'+focus.scope+'"]')?.querySelectorAll('button,a,input,select,[tabindex]')[focus.i]?.focus({preventScroll:true});}};
