// A live panel of a HOME / YARD render: its HTML is remembered so a poll can rebuild only the panels whose HTML changed. sel null = no element of its own (any change rebuilds the page).
const part=(key,sel,fn,morphs=false)=>{const html=fn();if(parts)parts.set(key,{sel,fn,html,morphs});return html;};
// Brings a live element in line with a freshly parsed copy, touching only the nodes that differ: the same DOM as replacing it, without re-creating the thousands of unchanged plan shapes or stockpile tiles (their hover, focus and scroll stay).
function morph(a,b){if(a.nodeType!==b.nodeType||a.nodeName!==b.nodeName){a.replaceWith(b);return;}if(a.nodeType!==1){if(a.nodeValue!==b.nodeValue)a.nodeValue=b.nodeValue;return;}if(a.isEqualNode(b))return;for(const n of a.getAttributeNames())if(!b.hasAttribute(n)&&!(n==='style'&&b.hasAttribute('data-style')))a.removeAttribute(n);for(const n of b.getAttributeNames()){const v=b.getAttribute(n);if(a.getAttribute(n)!==v)a.setAttribute(n,v);}const ac=a.childNodes,bc=[...b.childNodes];if(ac.length!==bc.length){a.replaceChildren(...bc);return;}for(let i=0;i<bc.length;i++)morph(ac[i],bc[i]);}
