   +'<div class="wk-id"><div class="wk-name"><strong>'+esc(r.name)+'</strong><small>'+esc(name(r.location))+(r.mountedOn?' – '+esc(name(r.mountedOn)):'')+'</small></div><span class="wk-pill '+k+'"><i></i>'+st+'</span><button type="button" class="secondary mode-chip wk-mode '+(auto?'current':'')+'" data-worker-order="'+(auto?'HOLD':'AUTO')+'" data-worker-id="'+r.id+'" aria-pressed="'+auto+'" '+(r.task||r.mountedOn?'disabled':'')+'><i class="wk-knob" aria-hidden="true"></i>'+(r.mountedOn?'Driving':auto?'Automatic':r.workerMode==='MOVING'?'Manual – walking on orders':'Manual – holding')+'</button><small class="mode-note">'+(r.mountedOn?'Unmount to return to automatic work':auto?'Takes forklift moves and yard jobs. Press to hold in place.':r.workerMode==='MOVING'?'Press to forget the order and return to the pool':'Holding – press to return to automatic work')+'</small>'+(r.workerReason?'<span class="error-text">'+esc(r.workerReason)+'</span>':'')+(task?.reason?'<span class="error-text">'+esc(task.reason)+'</span>':'')+'</div>'
