 const kinds=yard?'<div class="eq-kinds">'+eqCard('FORKLIFT','forklift',forks.length,'Forklifts',fBusy?'spr-forklift-driven':'spr-forklift',split(fBusy,forks.length,'in use','free'),fBusy,ops)+eqCard('WORKER','worker',crew.length,'Workers','spr-worker',split(wBusy,crew.length,'working','idle'),wBusy,ops)+eqCard('STILLAGE','stillage',packs.length,'Stillages','spr-stillage',split(sUsed,packs.length,'holding stock','empty'),sUsed,ops)+eqCard('TRUCK2','truck',light.length,'2 t trucks','spr-truck2',split(out(light),light.length,'out','at the yard'),out(light),ops)+eqCard('TRUCK12','truck',heavy.length,'12.5 t trucks','spr-truck12',split(out(heavy),heavy.length,'out','at the yard'),out(heavy),ops)+'</div>':'';
