// Counts for the hero and the list: live (not retired) components, missing unit weights / pack sizes, verification, components per system and the categories.
export function mlSummary(products){const out={total:0,noWeight:0,noPack:0,gaps:0,verified:0,demo:0,bySystem:new Map(),categories:new Set()};for(const p of products){if(p.retired)continue;out.total++;const w=p.unitWeight==null,k=p.packQuantity==null;if(w)out.noWeight++;if(k)out.noPack++;if(w||k)out.gaps++;if(p.verification==='SOURCE VERIFIED')out.verified++;else if(/DEMO/.test(p.verification??''))out.demo++;out.bySystem.set(p.system,(out.bySystem.get(p.system)??0)+1);out.categories.add(p.category||'Other');}return out;}
