export function mlGroups(products){const m=new Map();for(const p of products){const c=p.category||'Other';let a=m.get(c);if(!a)m.set(c,a=[]);a.push(p);}const rank=c=>{const i=ML_ORDER.indexOf(c);return i<0?ML_ORDER.length:i;};return [...m].sort((a,b)=>rank(a[0])-rank(b[0])||byText(a[0],b[0]));}
