export function mlStepQty(value,dir,unit){const v=Math.max(0,Math.floor(Number(value))||0),u=Math.max(1,Math.floor(Number(unit))||1);return Math.max(1,dir>0?Math.floor(v/u)*u+u:Math.ceil(v/u)*u-u);}
