const mlMark=id=>'<b class="ml-mark ml-sys-'+mlKey(id)+'" aria-hidden="true">'+esc(STK_SYS[id]??String(account.systems.find(s=>s.id===id)?.name??id??'').slice(0,2).toUpperCase())+'</b>';
const ML_VER={'SOURCE VERIFIED':['ok','Source verified'],'COMPANY CONFIGURED':['co','Company set'],'DEMO ONLY':['demo','Demo only'],'NEEDS REGIONAL CHECK':['warn','Regional check'],'CONFLICTING':['bad','Conflicting'],'NOT PROVIDED':['warn','Not provided']};
