 const rows=root.querySelectorAll('.ml-in-row:not([hidden])');if(rows.length){const p=inner(rows[0]);for(const r of rows){const h=r.getBoundingClientRect().height-p;if(h>0)mlH.set('r:'+r.dataset.focusScope.slice(7),+h.toFixed(2));}}
