  if(t.dataset.mlStep){const i=t.closest('[data-intake-row]')?.querySelector('[data-intake-qty]');if(!i)return;i.value=String(mlStepQty(i.value,Number(t.dataset.mlStep),t.dataset.mlUnit));mlQty.set(i.dataset.intakeQty,i.value);}
