function sgChip(x){const act=x.id==='yard'?sgBtn('shape','Change','text-button sg-chip-btn',' aria-label="Change the yard shape and size"'):x.id==='materials'&&x.gaps?sgBtn('gaps',num(x.gaps)+' missing figures &rarr;','text-button sg-chip-btn warn',' aria-label="Enter the '+x.gaps+' missing weights and pack sizes"'):'';
 return '<li class="sg-chip" data-sg-step="'+x.id+'"><span class="sg-chip-art">'+sgArt(SG_ART[x.id])+'<i class="sg-num" aria-hidden="true">'+SG_TICK+'</i></span><span class="sg-chip-text"><b>'+esc(x.title)+'</b><small>'+esc(x.detail)+'</small></span>'+act+'</li>';}
const sgStrip=(g,cls)=>'<div class="'+cls+' sg-reopen"><span class="sg-reopen-art">'+sprite('spr-stillage')+'</span><span class="sg-reopen-text"><b>Set-up guide hidden</b> &middot; '+g.done+' of '+g.total+' steps done</span>'+sgBtn('show','Show set-up guide &rarr;','text-button')+'</div>';
