const dims=loc=>{const pts=loc?.points??[];if(pts.length<3)return '';const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y);let area=0;for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length];area+=a.x*b.y-b.x*a.y;}return ((Math.max(...xs)-Math.min(...xs))/1000).toFixed(1)+' × '+((Math.max(...ys)-Math.min(...ys))/1000).toFixed(1)+' m · '+(Math.abs(area)/2e6).toFixed(1)+' m²';};
function resourceForm(location){if(!location)return '';return form('resources','Configure workers & equipment · DEMO ONLY',select('location','Location',[...state.yards,...state.sites.filter(s=>s.status==='ACTIVE')])+qty('workers',5)+number('machines','Forklifts (yard) / cranes (site)',1)+number('capacity','Machine capacity (grams)',1500000,1)+number('stepMs','Pickup / placement time (milliseconds)',700,100)+number('speed','Travel speed (mm per second)',4000,1)+number('craneWorkers','Workers required per crane task',1,1),'Save resources');}
