function componentsPanel(){const tabs=[{id:'ALL',name:'All components'},...account.systems.filter(s=>s.enabled)];const active=tabs.some(s=>s.id===componentTab)?componentTab:'ALL';const all=state.products.filter(p=>!p.retired),inTab=all.filter(p=>active==='ALL'||p.system===active),sum=mlSummary(inTab),products=mlGaps?inTab.filter(p=>p.unitWeight==null||p.packQuantity==null):inTab,groups=mlGroups(products),q=mlSearch.trim().toLowerCase(),counts=mlSummary(all).bySystem;mlText.clear();mlSig=active+'|'+mlGaps;
 // Per group: its tiles, how many show under the search and how many of those miss a figure; a figure missing on every component of the group is said once in a group note.
 let total=0;const built=groups.map(([cat,list])=>{const key=mlKey(cat),uw=list.length>1&&list.every(p=>p.unitWeight==null),uk=list.length>1&&list.every(p=>p.packQuantity==null);let shown=0,gaps=0,html='';for(const p of list){const t=mlHay(p);mlText.set(p.id,t);const hide=!!q&&!t.includes(q);if(!hide){shown++;if(p.unitWeight==null||p.packQuantity==null)gaps++;}html+=mlTile(p,active==='ALL',hide,uw,uk);}total+=shown;return {cat,key,uw,uk,shown,gaps,html,n:list.length};});
 const body=built.map(g=>{const open=!!q||(mlFold.get(g.key)??!mlPhone()),h=mlH.get('g:'+mlSig+'|'+g.key);return '<section class="ml-group'+(open?' open':'')+'" id="ml-cat-'+g.key+'" data-ml-group="'+g.key+'"'+(h?' data-style="contain-intrinsic-size:auto '+h+'px"':'')+(g.shown?'':' hidden')+'><h3 class="ml-group-h"><button type="button" class="ml-group-head" data-ml-fold aria-expanded="'+open+'" aria-controls="ml-list-'+g.key+'"><span class="ml-group-art">'+componentIcon({category:g.cat,name:''})+'</span><span class="ml-group-name">'+esc(g.cat)+'</span><span class="ml-group-count" data-ml-count>'+num(g.shown)+'</span>'+(mlGaps?'':mlGapBadge(g.gaps))+'<i class="ml-caret" aria-hidden="true"></i></button></h3>'+(g.uw||g.uk?'<p class="ml-group-note">'+mlUniNote(g.uw,g.uk,g.n)+'</p>':'')+'<ul class="ml-list" id="ml-list-'+g.key+'">'+g.html+'</ul></section>';}).join('');
 const jump=built.length>1?'<nav class="ml-jump" aria-label="Jump to a category" data-focus-scope="ml-jump">'+built.map(g=>'<a href="#ml-cat-'+g.key+'" class="ml-jump-chip" data-ml-jump="'+g.key+'"'+(g.shown?'':' hidden')+'>'+esc(g.cat)+' <b>'+num(g.shown)+'</b></a>').join('')+'</nav>':'';
 return '<section class="panel ml-card ml-cat" id="ml-catalogue">'+mlHead('ml-rack','Components','Every component you can order: its system, unit weight, pack size and where the figures come from.','<span class="ml-pill" data-ml-pill aria-live="polite">'+num(q?total:products.length)+' of '+num(all.length)+'</span>'+(all.length&&isOps()&&miSystems().length?'<button type="button" class="secondary ml-import-btn" data-mi-act="goto-import">'+MI_UP+'Import materials</button>':''))
 +'<div class="ml-chips" role="tablist" aria-label="Systems" data-focus-scope="ml-systems">'+tabs.map(s=>'<button type="button" class="secondary ml-chip '+(s.id===active?'current':'')+'" data-component-tab="'+s.id+'" role="tab" aria-selected="'+(s.id===active)+'">'+(s.id==='ALL'?'':mlMark(s.id))+esc(s.name)+'<small>'+num(s.id==='ALL'?all.length:counts.get(s.id)??0)+'</small></button>').join('')+'</div>'
 +(inTab.length?'<div class="ml-tools" data-focus-scope="ml-tools"><label class="ml-search">Search the catalogue<span class="ml-search-box"><i class="ml-glass" aria-hidden="true"></i><input id="ml-search" type="search" data-live-search placeholder="Name, reference, category…" value="'+esc(mlSearch)+'"></span></label><button type="button" class="secondary ml-gaps-btn'+(mlGaps?' current':'')+'" data-ml-gaps aria-pressed="'+mlGaps+'">'+mlImg('ml-scale','ml-gaps-art')+'<span>Missing figures only</span><b>'+num(sum.gaps)+'</b></button></div>'+jump:'')+miGapsCallout(sum)
 +(inTab.length?'<div class="ml-groups" data-focus-scope="ml-groups">'+body+(products.length?'':mlEmpty('ml-scale','Every figure is in','Each component here has a unit weight and a pack size.'))+'<p class="ml-none" data-ml-none'+(total||!products.length?' hidden':'')+'>Nothing matches <b data-ml-q>'+esc(mlSearch.trim())+'</b>. Try a shorter word or another system.</p></div>':mlEmpty('ml-rack',all.length?'No components in this system yet':'Your catalogue is empty',all.length?'Pick another system. '+miWhere('below'):'Every component you can order is listed here. '+miWhere('above')))+'</section>';}
const when=iso=>{try{return new Date(iso).toLocaleString();}catch{return esc(iso);}};
const storageContainers=()=>state.containers.filter(c=>state.yards.some(y=>y.id===c.location)||state.sites.some(y=>y.id===c.location));
