// ----- Stock as the warehouse ledger: a hero with stock counters and a stacked-stillage scene, the tabs as a segmented control, ledger tables with component icons, system chips, where-bars (in yard / at sites / on trucks), reserved vs available, condition pills. Bars are SVG rects, not inline styles (the CSP allows none). -----
const STK_ART='<svg class="stk-scene" viewBox="0 0 460 210" aria-hidden="true"><path d="M-10 146 236 38 470 132 224 250Z" fill="#8fa866"/><path d="M40 150 236 64 440 146 244 232Z" fill="#d8d1c1"/><path d="M40 150 244 232 440 146v7L244 239 40 157Z" fill="#a79f8b"/><path d="M70 150 236 78 410 146 244 218Z" fill="none" stroke="#e3bd2c" stroke-width="2" stroke-dasharray="9 6" opacity=".9"/>'+
 '<use href="#spr-tree" x="0" y="54" width="66" height="78"/><use href="#spr-tree" x="400" y="30" width="54" height="64"/>'+
 '<use href="#spr-stillage" x="116" y="100" width="88" height="58"/><use href="#spr-stillage" x="116" y="65" width="88" height="58"/><use href="#spr-stillage" x="116" y="30" width="88" height="58"/>'+
 '<use href="#spr-cage" x="226" y="66" width="68" height="45"/><use href="#spr-cage" x="226" y="36" width="68" height="45"/>'+
 '<use href="#spr-stillage" x="186" y="130" width="88" height="58"/><use href="#spr-stillage" x="186" y="95" width="88" height="58"/>'+
 '<use href="#spr-bundle" x="76" y="160" width="56" height="41"/><use href="#spr-worker" x="100" y="146" width="24" height="46"/>'+
 '<use href="#spr-forklift-load" x="292" y="112" width="104" height="80"/></svg>';
const STK_TAB_ICON={REGISTER:'M6 3h10l3 3v15H6zM9.5 9h6M9.5 13h6M9.5 17h3.5',ADDED:'M12 4v10M7.5 10l4.5 4.5 4.5-4.5M4 20h16',REMOVED:'M12 15V4M7.5 8.5 12 4l4.5 4.5M4 20h16',CONTAINERS:'m3 8.5 9-4.5 9 4.5-9 4.5zM3 8.5v7.5l9 4.5 9-4.5V8.5M12 13v7.5',COMPONENTS:'M5 19 19 5M3.5 15.5l5 5M15.5 3.5l5 5'};
