let stkKeep=null,stkSearch='';
// One bar: parts [[value,class]...] against total, drawn as rects in a 100 x 6 box (the track is the svg's CSS background).
const stkBar=(parts,total,cls='')=>{let x=0,s='';if(total>0)for(const [v,c] of parts){if(!(v>0))continue;const w=Math.min(100-x,v*100/total);s+='<rect class="'+c+'" x="'+(+x.toFixed(2))+'" width="'+(+w.toFixed(2))+'" height="6"/>';x+=w;}return '<svg class="stk-bar'+(cls?' '+cls:'')+'" viewBox="0 0 100 6" preserveAspectRatio="none" aria-hidden="true">'+s+'</svg>';};
