const stkItem=(p,label,sub)=>'<span class="stk-slot">'+componentIcon(p??{name:label})+'</span><span class="stk-name"><strong>'+esc(label).replace(/ — (\S+) (m|mm|kg)\b/g,'&nbsp;—&nbsp;$1&nbsp;$2')+'</strong>'+(sub?'<small>'+esc(sub)+'</small>':'')+'</span>';
const stkPack=type=>sprite(type==='CAGE'?'spr-cage':type==='BUNDLE'?'spr-bundle':'spr-stillage','stk-pack');
const stkWord=v=>{const t=String(v??'').replaceAll('_',' ').toLowerCase();return esc(t.charAt(0).toUpperCase()+t.slice(1));};
const stkCond=c=>'<span class="stk-cond '+(c==='SERVICEABLE'?'good':c==='DAMAGED'?'bad':'warn')+'">'+stkWord(c)+'</span>';
