const stkProducts=()=>new Map(state.products.map(p=>[p.id,p]));
// A rebuild (a poll, Pause, a selection) keeps what the viewer was doing: open folds with their typed values, the search and loaded history are read from the page being replaced and put back (stkBind). A fold whose form was just submitted (its button is disabled while it saves) closes as before.
function stkCapture(){if(typeof document==='undefined')return null;const root=document.querySelector('.page-stock');if(!root)return null;const s=root.querySelector('#stock-search');if(s)stkSearch=s.value;const open=[...root.querySelectorAll('details[data-stk-fold][open]')].filter(d=>!d.querySelector('form button:not([type=button]):disabled'));return {open:new Set(open.map(d=>d.dataset.stkFold)),forms:open.flatMap(d=>[...d.querySelectorAll('form[id]')]).map(f=>[f.id,[...f.elements].filter(e=>e.name&&!['button','submit'].includes(e.type)).map(e=>[e.name,e.value])]),history:root.querySelector('#history')?.innerHTML??''};}
const stkPillText=(shown,total,boxes,filtered)=>(filtered?num(shown)+' of '+num(total)+(total===1?' line':' lines'):num(total)+(total===1?' line':' lines'))+' · '+num(boxes)+(boxes===1?' stillage / cage':' stillages / cages');
function stkFilter(value){const q=String(value??'').trim().toLowerCase(),rows=[...document.querySelectorAll('[data-stock-row]')],boxes=new Set();let shown=0;for(const row of rows){row.hidden=!!q&&!row.textContent.toLowerCase().includes(q);if(!row.hidden){shown++;boxes.add(row.dataset.box);}}const pill=document.querySelector('[data-stk-pill]');if(pill)pill.textContent=stkPillText(shown,rows.length,boxes.size,!!q);}
function stkBind(){if(!document.querySelector('.page-stock'))return;const k=stkKeep;if(k){for(const [id,vals] of k.forms){const f=document.getElementById(id);if(f)for(const [n,v] of vals){const e=f.elements.namedItem(n);if(e&&'value' in e)try{e.value=v;}catch{}}}k.forms=[];}if(stkSearch.trim())stkFilter(stkSearch);}
function stkHero(){const reg=state.register??[],total=state.stockTotal??0,reserved=state.reservedTotal??0,free=Math.max(0,total-reserved);let yard=0,site=0,truck=0,lines=0;for(const r of reg){yard+=r.yard;site+=r.site;truck+=r.truck;if(r.quantity>0)lines++;}
 const boxes=state.containers,full=new Set();for(const l of state.balances)if(l.quantity>0)full.add(l.container);const held=boxes.filter(c=>full.has(c.id)).length,count=Math.max(state.containerCount??0,boxes.length),paged=count>boxes.length,where=yard+site+truck;
 const stat=(art,label,value,sub,bar,cls='')=>'<div class="stk-stat'+cls+'" role="listitem"><span class="stk-stat-art">'+sprite(art)+'</span><span class="stk-stat-text"><span class="stk-stat-label">'+label+'</span><b class="stk-stat-num">'+value+'</b>'+(bar??'')+'<span class="stk-stat-sub">'+sub+'</span></span></div>';
 const key=(cls,label,v)=>'<span class="stk-key '+cls+'"><i aria-hidden="true"></i>'+label+' <b>'+num(v)+'</b></span>';
 return '<div class="stk-hero page-hero"><div class="stk-hero-art">'+STK_ART+'</div><div class="stk-hero-top">'+heroEyebrow()+'<h1>Stock ledger</h1><p class="stk-hero-sub hero-sub">Every piece, every stillage: what you own, where it sits and what is free to load.</p>'+heroActions()+'<div class="stk-where" aria-label="Where the stock is">'+stkBar([[yard,'yard'],[site,'site'],[truck,'truck']],where,'where')+'<div class="stk-keys">'+key('yard','In yard',yard)+key('site','At sites',site)+key('truck','On trucks',truck)+'</div></div></div>'+
  '<div class="stk-stats" role="list" aria-label="Stock at a glance">'+stat('spr-bundle','Physical pieces',num(total),lines===1?dual('1 component on hand','1 component'):dual(num(lines)+' components on hand',num(lines)+' components'))+stat('spr-stillage','Available',num(free),total?share(free,total)+'% unreserved':'Nothing on hand yet',stkBar([[free,'free']],total))+stat('spr-forklift-load','Reserved',num(reserved),reserved?'Held for loads &middot; in physical':'Nothing held',stkBar([[reserved,'held']],total),reserved?' held':'')+stat('spr-cage',dual('Stillages &amp; cages','Storage'),num(count),paged?dual(num(held)+' of the first '+num(boxes.length)+' hold stock',num(held)+' of '+num(boxes.length)+' hold stock'):dual(num(held)+' holding stock &middot; '+num(boxes.length-held)+' empty',num(held)+' full &middot; '+num(boxes.length-held)+' empty'),stkBar([[held,'free']],boxes.length))+'</div>'+heroBanner()+'</div>';}
function stockTabs(){const n={REGISTER:(state.register??[]).length,ADDED:(state.additions??[]).length,REMOVED:(state.removals??[]).length,CONTAINERS:state.balances.length,COMPONENTS:state.products.filter(p=>!p.retired).length};const tabs=[['REGISTER','Materials register'],['ADDED','Added stock'],['REMOVED','Removed stock'],['CONTAINERS','Stillages & cages'],['COMPONENTS','Components']];return '<div class="subtabs stk-tabs" role="tablist" aria-label="Stock views" data-focus-scope="stock-tabs">'+tabs.map(([id,label])=>'<button type="button" class="secondary stk-tab '+(id===stockTab?'current':'')+'" data-stock-tab="'+id+'" role="tab" aria-selected="'+(id===stockTab)+'"><svg class="stk-tab-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+STK_TAB_ICON[id]+'"/></svg><span class="stk-tab-label">'+label+'</span><span class="stk-tab-count" aria-hidden="true">'+num(n[id])+'</span></button>').join('')+'</div>';}
function registerPanel(){const rows=state.register??[],P=stkProducts(),demo=purgeButton();return (demo?'<div class="stk-demo"><span class="stk-demo-tag" aria-hidden="true">DEMO</span>'+demo+'</div>':'')+'<section class="panel stk-panel">'+stkHead('spr-bundle','Materials register','Total stock the company owns right now, per product, across the yard, sites and trucks. This is the original list of stock plus everything added, minus everything removed.',stkExport('register','Export register CSV'))+'<div class="table-scroll"><table class="stk-table stk-register"><thead><tr><th>Product</th><th>System</th><th class="num">In yard</th><th class="num">At sites</th><th class="num">On trucks</th><th class="num">Total</th><th class="num">Reserved</th><th class="num">Available</th></tr></thead><tbody>'+rows.map(r=>'<tr><td class="stk-first" data-label="Product">'+stkItem(P.get(r.product),r.name,r.category)+'</td><td data-label="System">'+stkSys(r.system)+'</td>'+stkQty(r.yard,'yard','In yard')+stkQty(r.site,'site','At sites')+stkQty(r.truck,'truck','On trucks')+'<td class="num stk-total" data-label="Total"><strong>'+num(r.quantity)+'</strong>'+stkBar([[r.yard,'yard'],[r.site,'site'],[r.truck,'truck']],r.quantity)+'</td>'+stkRes(r.reserved)+'<td class="num stk-avail" data-label="Available"><strong>'+num(r.available)+'</strong></td></tr>').join('')+(rows.length?'':stkEmptyRow(8,'spr-stillage','Nothing on the books yet','No stock has been recorded yet. Record your original stock below.'))+'</tbody></table></div></section>'+(account.permissions.includes('stock.adjust')?stkFold('opening','Record original stock (opening balance)','Put what is already in a stillage or cage on the books','spr-stillage',select('container','Stillage / cage',storageContainers())+select('product','Product',enabledProducts())+qty()+text('reason','Reason','Original stock on hand'),'Record original stock'):'');}
function stockLogTable(rows,empty,out=false){const P=stkProducts(),C=new Map(state.containers.map(c=>[c.id,c]));return '<div class="table-scroll"><table class="stk-table stk-log"><thead><tr><th>When</th><th>Product</th><th class="num">Quantity</th><th>Stillage / cage</th><th>Location</th><th>Reason</th></tr></thead><tbody>'+rows.map(l=>'<tr><td class="stk-when" data-label="When">'+when(l.created_at)+'<small class="stk-event '+(l.event==='PURCHASE'?'buy':l.event==='OPENING_BALANCE'?'open':'out')+'">'+stkWord(l.event)+'</small></td><td class="stk-first" data-label="Product">'+stkItem(P.get(l.product_id),P.get(l.product_id)?.name??name(l.product_id))+'</td><td class="num" data-label="Quantity"><span class="stk-delta '+(out?'out':'in')+'">'+(out?'&minus;':'+')+num(l.quantity)+'</span></td><td data-label="Stillage / cage"><span class="stk-box">'+stkPack(C.get(l.container_id)?.type)+'<span>'+esc(C.get(l.container_id)?.name??name(l.container_id))+'</span></span></td><td data-label="Location">'+esc(name(l.destination??l.source))+'</td><td class="stk-reason" data-label="Reason">'+esc(l.reason)+'</td></tr>').join('')+(rows.length?'':stkEmptyRow(6,out?'spr-truck2':'spr-stillage','',empty))+'</tbody></table></div>';}
function additionsPanel(){return '<section class="panel stk-panel">'+stkHead('spr-forklift-load','Added stock','Every purchase and original-stock receipt, newest first.',stkExport('additions','Export additions CSV'))+stockLogTable(state.additions??[],'Nothing has been added yet.')+'</section>'+(account.permissions.includes('stock.adjust')?stkFold('purchase','Record a purchase','Receive new stock into a stillage or cage','spr-forklift-load',select('container','Receive into stillage / cage',storageContainers())+select('product','Product',enabledProducts())+qty()+'<label>Supplier (optional)<input name="supplier" maxlength="250"></label>'+text('reason','Reason / invoice reference','Purchased stock'),'Add purchased stock'):'');}
function removalsPanel(){return '<section class="panel stk-panel">'+stkHead('spr-truck2','Removed stock','Stock sold, scrapped or otherwise taken out of the company, newest first. Reserved, in-transit and counted stock cannot be removed.',stkExport('removals','Export removals CSV'))+stockLogTable(state.removals??[],'Nothing has been removed yet.',true)+'</section>'+(account.permissions.includes('stock.adjust')?stkFold('remove-stock','Record a sale / removal','Take sold or scrapped stock off the books','spr-truck2',select('container','Remove from stillage / cage',storageContainers().filter(c=>state.balances.some(l=>l.container===c.id)))+select('product','Product',enabledProducts())+qty('quantity',10)+text('reason','Reason / sale reference','Sold to customer'),'Remove stock'):'');}
function stkContainersPanel(){const P=stkProducts(),C=new Map(state.containers.map(c=>[c.id,c])),places=new Map([...state.yards.map(y=>[y.id,['yard',y.name]]),...state.sites.map(s=>[s.id,['site',s.name]]),...state.trucks.map(t=>[t.id,['truck',t.name]])]),boxes=new Set(state.balances.map(l=>l.container)).size;
 const rows=state.balances.map(l=>{const c=C.get(l.container),at=places.get(l.location),avail=l.condition==='SERVICEABLE'?l.quantity-l.reserved:0;return '<tr data-stock-row data-box="'+esc(l.container)+'"><td class="stk-first" data-label="Product">'+stkItem(P.get(l.product_id),P.get(l.product_id)?.name??name(l.product_id))+'</td><td data-label="Stillage / cage"><span class="stk-box">'+stkPack(c?.type)+'<span><button class="text-button" data-select="'+l.container+'">'+esc(c?.name??name(l.container))+'</button><small class="stk-loc '+(at?.[0]??'yard')+'">'+esc(at?.[1]??name(l.location))+'</small></span></span></td><td class="num" data-label="Physical"><strong>'+num(l.quantity)+'</strong></td>'+stkRes(l.reserved)+'<td class="num stk-avail'+(avail?'':' none')+'" data-label="Available"><strong>'+num(avail)+'</strong>'+(l.reserved?stkBar([[avail,'free'],[l.reserved,'held']],l.quantity):'')+'</td><td data-label="Condition">'+stkCond(l.condition)+'</td></tr>';}).join('');
 return '<section class="panel stk-panel">'+stkHead('spr-stillage','Stock by stillage &amp; cage','Each line is one product in one stillage or cage. Select a stillage or cage to see it and move it.',stkExport('stock','Export stock CSV'))+'<div class="stk-tools"><label class="stk-search">Search product or stillage / cage<span class="stk-search-box"><i class="stk-glass" aria-hidden="true"></i><input id="stock-search" type="search" data-live-search placeholder="Ledger, S-001…" value="'+esc(stkSearch)+'"></span></label><span class="stk-pill" data-stk-pill aria-live="polite">'+stkPillText(state.balances.length,state.balances.length,boxes,false)+'</span></div><div class="table-scroll"><table class="stk-table stk-boxes" aria-label="Stock by stillage & cage"><thead><tr><th>Product</th><th>Stillage / cage / location</th><th class="num">Physical</th><th class="num">Reserved</th><th class="num">Available</th><th>Condition</th></tr></thead><tbody>'+(rows||stkEmptyRow(6,'spr-stillage','Every stillage is empty','No stock has been received.'))+'</tbody></table></div></section>';}
function stkComponentsPanel(){const tabs=[{id:'ALL',name:'All components'},...account.systems.filter(s=>s.enabled)],active=tabs.some(s=>s.id===componentTab)?componentTab:'ALL',all=state.products.filter(p=>!p.retired),products=all.filter(p=>active==='ALL'||p.system===active);
 return '<section class="panel stk-panel">'+stkHead('spr-cage','Components','Every component in your catalogue: its system, unit weight, pack size and where the figures come from.','<span class="stk-pill">'+products.length+' of '+all.length+'</span>')+'<div class="stk-chips" role="tablist" aria-label="Systems">'+tabs.map(s=>'<button type="button" class="secondary stk-chip '+(s.id===active?'current':'')+'" data-component-tab="'+s.id+'" role="tab" aria-selected="'+(s.id===active)+'">'+(s.id==='ALL'?'':stkMark(s.id))+esc(s.name)+'</button>').join('')+'</div><div class="table-scroll"><table class="stk-table stk-components"><thead><tr><th>Name</th><th>System</th><th>Category</th><th>Manufacturer / reference</th><th class="num">Unit weight</th><th class="num">Pack qty</th><th>Verification</th></tr></thead><tbody>'+(products.map(p=>'<tr><td class="stk-first" data-label="Name">'+stkItem(p,p.name)+'</td><td data-label="System">'+stkSys(p.system)+'</td><td data-label="Category">'+esc(p.category)+'</td><td data-label="Manufacturer / reference">'+esc(p.manufacturer)+'<small>'+esc(p.reference)+'</small></td><td class="num" data-label="Unit weight">'+(p.unitWeight!==null?kg(p.unitWeight):'<span class="stk-nil">Unknown</span>')+'</td><td class="num" data-label="Pack qty">'+(p.packQuantity??'&mdash;')+'</td><td data-label="Verification">'+stkVerify(p.verification)+'</td></tr>').join('')||stkEmptyRow(7,'spr-cage','','No components in this system yet.'))+'</tbody></table></div></section>';}
function stkCounts(){return state.counts.map(c=>`<section class="panel stk-panel stk-count" data-focus-scope="count:${c.id}"><h2><span class="stk-art">${sprite('spr-worker')}</span><span>Stocktake · ${esc(c.name)}</span> <span class="badge stk-state ${c.state==='OPEN'?'open':''}">${c.state}</span></h2>${c.state==='OPEN'?`<p class="stk-count-sum"><span class="stk-pill">${c.lines.length===1?'1 line':num(c.lines.length)+' lines'} to count</span><span class="stk-pill">${num(c.lines.reduce((n,l)=>n+l.expected,0))} pieces expected</span>${c.lines.every(l=>l.observed!==null)?'<span class="stk-pill done">Counts saved</span>':''}</p><form data-count="${c.id}">${c.lines.map((l,i)=>number(`line${i}`,`${name(l.product_id)} in ${name(l.container)} · expected ${l.expected}`,l.observed??l.expected)).join('')}${text('reason','Reason for any variance',c.reason??'')}<div class="actions"><button>Save observed counts</button>${c.lines.every(l=>l.observed!==null)?`<button type="button" data-approve="${c.id}">Approve correction</button>`:''}<button type="button" class="secondary" data-cancel-count="${c.id}">Cancel count</button></div></form>`:`<div class="stk-count-done"><p>${esc(c.reason??'Count cancelled')}</p><p>${c.lines.map(l=>`${esc(name(l.product_id))}: ${l.expected} expected → ${l.observed??'—'} counted`).join('<br>')}</p></div>`}</section>`).join('');}
const STK_EV={OPENING_BALANCE:'Opening balance',PURCHASE:'Purchase',STOCK_REMOVED:'Stock removed',PICKUP:'Picked up',PLACEMENT:'Put down',REPACK_PICKUP:'Repack pick-up',CONDITION:'Condition changed',CONSOLIDATED:'Consolidated',CONTAINER_RETIRED:'Stillage / cage retired',CONTAINER_SETTINGS:'Stillage / cage settings',DEMO_PURGED:'Demo stock removed',LAYOUT_PLANNED:'Layout planned',PRODUCT_OVERRIDE:'Component details changed',RELOCATED:'Relocated',SITE_ARCHIVED:'Site archived',SITE_DETAILS:'Site details changed',SORTED:'Sorted',STOCKTAKE_ADJUSTMENT:'Stocktake correction',TURNED:'Turned',TURN_PLANNED:'Turn planned'};
const STK_CMD={yard:'Yard shape saved',resources:'Crew and equipment set',seed:'Catalogue loaded',container:'Stillage / cage created',opening:'Opening balance recorded',purchase:'Purchase recorded',stockRemoval:'Stock removal recorded',site:'Site created',quickAdjust:'Fleet changed',loadTruck:'Truck loading requested',dispatch:'Truck dispatched',unload:'Truck unloaded',jobsMode:'Job settings changed',count:'Stocktake started',observe:'Counts saved',approveCount:'Stocktake approved',cancelCount:'Stocktake cancelled'};
const stkHuman=v=>{const t=String(v??'').replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' ').toLowerCase();return esc(t.charAt(0).toUpperCase()+t.slice(1));};
function stkHistRows(rows){if(!rows.length)return '<p class="stk-hist-none">No more records.</p>';const P=stkProducts(),C=new Map(state.containers.map(c=>[c.id,c])),nil='<span class="stk-nil">&mdash;</span>';
 return '<table class="stk-table stk-log stk-hist" aria-label="Movement and adjustment history"><thead><tr><th>When</th><th>Record</th><th class="num">Quantity</th><th>Stillage / cage</th><th>Location</th><th>Details</th></tr></thead><tbody>'+rows.map(l=>{const cmd=l.event==='COMMAND',label=cmd?(STK_CMD[l.reason]??stkHuman(l.reason)):(STK_EV[l.event]??stkHuman(l.event)),kind=l.event==='PURCHASE'?'buy':l.event==='OPENING_BALANCE'?'open':l.event==='STOCK_REMOVED'?'out':'move',p=l.product_id?P.get(l.product_id):null,c=l.container_id?C.get(l.container_id):null,where=l.destination??l.source,detail=cmd||l.reason===l.event?'':l.reason,sign=kind==='out'?'&minus;':kind==='move'?'':'+';
  return '<tr><td class="stk-when" data-label="When">'+when(l.created_at)+'<small class="stk-event '+kind+'">'+(cmd?'Action':label)+'</small></td><td class="stk-first" data-label="Record">'+(l.product_id?stkItem(p,p?.name??name(l.product_id)):'<span class="stk-hist-what">'+label+' <small>#'+num(l.sequence)+'</small></span>')+'</td><td class="num" data-label="Quantity">'+(l.quantity?'<span class="stk-delta '+(kind==='out'?'out':kind==='move'?'move':'in')+'">'+sign+num(l.quantity)+'</span>':nil)+'</td><td data-label="Stillage / cage">'+(l.container_id?'<span class="stk-box">'+stkPack(c?.type)+'<span>'+esc(c?.name??name(l.container_id))+'</span></span>':nil)+'</td><td data-label="Location">'+(where?esc(name(where)):nil)+'</td><td class="stk-reason" data-label="Details">'+(detail?esc(detail):nil)+'</td></tr>';}).join('')+'</tbody></table>';}
function stkHistory(){return '<details class="panel stk-fold stk-history" data-stk-fold="history"'+(stkKeep?.open.has('history')?' open':'')+'><summary><span class="stk-art">'+sprite('spr-forklift')+'</span><span class="stk-fold-text"><b>Movement and adjustment history</b><small>Every stock record, 100 at a time</small></span></summary><div class="actions"><button id="load-history">Load next 100 records</button><a href="/api/export?kind=history">Export history CSV (up to 10,000)</a></div><div id="history">'+(stkKeep?.open.has('history')?stkKeep.history:'')+'</div></details>';}
const listBadge=s=>({OPEN:'busy',PARTIAL:'busy',RESERVED:'available',LOADED:'available',IN_TRANSIT:'available',AT_SITE:'available',DELIVERED:'available',CANCELLED:''}[s]??'');
function loadListCard(l,controls){const ops=account.permissions.includes('operations.manage');const truckSelect=state.trucks.filter(t=>t.status==='AT_YARD'&&(!t.destination||t.destination===l.site)),dated=l.urgency!==undefined,it=dated?schedItems().find(i=>i.id===l.id):null;return '<section class="panel load-list'+(schFlash.id===l.id&&Date.now()<schFlash.until?' sch-flash':'')+'" data-load-list="'+l.id+'"><div class="row"><h2>'+esc(l.name)+'</h2><span class="sch-badges">'+(dated&&!l.cancelled?whenBadge(l)+slotTag(l.slot):'')+'<span class="badge '+listBadge(l.status)+'">'+esc(l.status.replaceAll('_',' '))+(l.short&&!['OPEN','CANCELLED'].includes(l.status)?' · '+l.short+' short':'')+'</span></span></div><p>'+(dated&&['TODAY','TOMORROW','OVERDUE'].includes(l.urgency)?'Needed <strong>'+dLabel(l.neededOn)+'</strong> · ':'')+'To <strong>'+esc(name(l.site))+'</strong>'+(l.truckName?' · truck <strong>'+esc(l.truckName)+'</strong>':'')+(l.plannedTruck&&!l.truck?' · planned truck <b>'+esc(l.plannedTruckName??name(l.plannedTruck))+'</b>':'')+(dated&&l.clash>0?' '+schClash(l):'')+' · '+l.requested+' pieces requested · '+(l.delivery?l.lines.reduce((s,x)=>s+(x.sent??0),0)+' sent':l.loaded+' on truck')+' · '+l.delivered+' at site'+(l.departedAt?' · departed '+when(l.departedAt):'')+(l.notes?' · '+esc(l.notes):'')+'</p><div class="table-scroll"><table><thead><tr><th>Product</th><th>Requested</th><th>Reserved</th><th>'+(l.delivery?'Sent':'On truck')+'</th><th>At site</th><th>Line</th></tr></thead><tbody>'+l.lines.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+x.quantity+'</td><td>'+x.reserved+'</td><td>'+(l.delivery?(x.sent??0)+(x.sent?'':' <small>not sent</small>'):x.loaded)+'</td><td>'+x.delivered+'</td><td><span class="badge '+(x.status==='DELIVERED'?'available':x.status==='REQUESTED'?'busy':'')+'">'+esc(x.status.replaceAll('_',' '))+'</span>'+(x.lastReason&&x.status==='REQUESTED'?'<br><span class="error-text">'+esc(x.lastReason)+'</span>':'')+'</td></tr>').join('')+'</tbody></table></div>'+(controls&&!l.cancelled&&it&&((it.schedulable&&it.canReschedule&&cal())||(ops&&it.schedulable&&!l.truck))?'<div class="sch-list-edit" data-focus-scope="sch:list:'+l.id+'">'+(it.schedulable&&it.canReschedule&&cal()?schDateForm(it,it.neededOn?'Change date':'Set a date',' compact',true):'')+(ops&&it.schedulable&&!l.truck?schBookForm(it,' compact','Planned truck'):'')+'</div>':'')+(controls&&!l.cancelled?'<div class="actions">'+(ops&&l.lines.some(x=>x.status==='REQUESTED')?'<form data-allocate-list="'+l.id+'" class="inline-form">'+(truckSelect.length?'<label>Loading truck<select name="truck" required>'+(l.plannedTruck&&truckSelect.some(t=>t.id===l.plannedTruck)?'':'<option value="" selected>Choose a truck</option>')+options(truckSelect,'name',l.plannedTruck??null)+'</select></label><button>Reserve packs &amp; load truck</button>':'<span class="muted">No truck at the yard for this site.</span>')+'</form>':'')+(!['DELIVERED'].includes(l.status)?'<button type="button" class="secondary" data-cancel-list="'+l.id+'">Cancel remaining lines</button>':'')+'</div>':'')+(l.cancelled&&l.cancelReason?'<p class="muted">Cancelled: '+esc(l.cancelReason)+'</p>':'')+'</section>';}
function loadListForm(){const products=enabledProducts(),sites=state.sites.filter(s=>s.status==='ACTIVE');if(!sites.length||!products.length)return '';const row=i=>'<div class="load-line"><label>Product<select name="product'+i+'"><option value="">— none —</option>'+options(products)+'</select></label><label>Quantity<input type="number" name="quantity'+i+'" min="0" step="1" value="0"></label></div>';return '<details class="panel" id="load-list-panel"><summary><span class="si-form-title">'+siImg('si-docket','si-form-art')+'<span>Create a yard list<small>A load list for one truck; it travels as the delivery docket</small></span></span></summary><form id="load-list"><p>List everything the yardsman must put on the truck for this site. The same list travels with the truck as the delivery docket. Each product once; leave unused lines at 0.</p>'+text('name','Yard list name','Yard list '+(cal()?.today??new Date().toISOString().slice(0,10)))+select('site','Destination site',sites)+schDateFields()+'<label>Notes<input name="notes" maxlength="250" value="Demonstration delivery"></label><div id="load-lines">'+[0,1,2,3].map(row).join('')+'</div><div class="actions"><button type="button" class="secondary" id="add-load-line">Add another line</button><button>Create yard list</button></div></form></details>';}
function yardListsPanel(filter,controls){const lists=(state.loadLists??[]).filter(filter);if(!lists.length)return '';return lists.map(l=>loadListCard(l,controls)).join('');}
function manifestPanel(delivery,title){const lists=delivery?.manifest??[];if(!lists.length)return '';return '<section class="panel"><div class="row"><h2>'+title+'</h2><span class="badge">'+esc(delivery.status)+'</span></div><p>'+esc(name(delivery.from))+' → '+esc(name(delivery.to))+' · '+delivery.containers.length+' stillages / cages · '+when(delivery.createdAt)+'</p>'+lists.map(l=>loadListCard(l,false)).join('')+'</section>';}
function stockView(){stkKeep=stkCapture();return '<div class="page-stock">'+stkHero()+stockTabs()+(stockTab==='REGISTER'?registerPanel():stockTab==='ADDED'?additionsPanel():stockTab==='REMOVED'?removalsPanel():stockTab==='COMPONENTS'?stkComponentsPanel():stkContainersPanel()+(account.permissions.includes('operations.manage')?stkFold('count','Start a stocktake','Lock a yard, site or stillage while you count it','spr-worker',select('scope','Count scope',[...state.yards,...state.sites,...state.containers]),'Start count and lock scope'):'')+stkCounts()+stkHistory())+'</div>';}
// Sprites on these pages are cached images of the sheet's own symbols (built once from the mounted sheet): every render re-creates the page, and an <img> of a cached picture is far cheaper than a <use> that clones ~60 truck shapes each time. Falls back to sprite() when there is no DOM.
const trkPics=new Map();
function trkPicURL(key,build){let u=trkPics.get(key);if(u)return u;try{const svg=typeof document!=='undefined'&&typeof URL!=='undefined'&&URL.createObjectURL?build():null;if(!svg)return null;u=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));trkPics.set(key,u);return u;}catch{return null;}}
const trkSym=id=>{const s=document.getElementById(id);return s?'<symbol id="'+id+'" viewBox="'+s.getAttribute('viewBox')+'">'+s.innerHTML+'</symbol>':null;};
const trkPic=(id,cls='')=>{const u=trkPicURL(id,()=>{const s=document.getElementById(id);return s&&'<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+s.getAttribute('viewBox')+'">'+s.innerHTML+'</svg>';});return u?'<img class="sprite'+(cls?' '+cls:'')+'" src="'+u+'" alt="" aria-hidden="true" draggable="false">':sprite(id,cls);};
// A small scene (drawn with <use> of the sheet's symbols) as one cached picture; the symbols it uses travel inside it.
const trkScenePic=(key,body)=>{const u=trkPicURL('scene:'+key,()=>{const ids=[...new Set([...body.matchAll(/href="#([^"]+)"/g)].map(m=>m[1]))],defs=ids.map(trkSym);return defs.every(Boolean)?'<svg xmlns="http://www.w3.org/2000/svg" width="440" height="190" viewBox="0 0 440 190"><defs>'+defs.join('')+'</defs>'+body+'</svg>':null;});return u?'<img class="tk-scene" src="'+u+'" alt="">':'<svg viewBox="0 0 440 190" class="tk-scene">'+body+'</svg>';};
// ---- Truck pages as a garage: a card per truck built around its 3/4 deck art, with a status ribbon, payload and deck gauges, the trip, a tidy action area (the shared load picker and the dispatch form) and the cargo as stillage slots. Sprites come from the shared sheet (art.js spriteSheet). ----
// A green band in the Home hero style (eyebrow, title, a small scene, live counters); the truck and equipment pages share it.
const trkStat=(art,label,value,sub,fill=null,cls='')=>'<div class="hud-stat'+cls+'" role="listitem"><span class="hud-icon">'+trkPic(art)+'</span><span class="hud-text"><span class="hud-label">'+label+'</span><b class="hud-num">'+value+'</b>'+(fill==null?'':'<i class="hud-bar" aria-hidden="true"><b data-style="width:'+fill+'%"></b></i>')+'<span class="hud-sub">'+sub+'</span></span></div>';
