 for(const r of state.requests??[]){if(r.loadList||r.status==='CANCELLED')continue;const run=r.runTruck??r.truck??null;items.push({kind:'request',id:r.id,name:r.name??(r.quantity+' × '+name(r.product)),site:r.site,siteName:r.siteName??name(r.site),neededOn:r.neededOn??null,slot:r.slot??'ANY',urgency:r.urgency??'UNDATED',daysLate:r.daysLate??0,runTruck:run,runTruckName:r.runTruckName??(run?name(run):null),reserved:!!r.truck,pieces:r.quantity,status:r.status,schedulable:!!r.schedulable,canReschedule:!!r.canReschedule,clash:r.clash??0,clashWith:r.clashWith??[],hasRequested:r.status==='REQUESTED'});}
