 const items=schedItems(),ops=isOps(),ws=schedWeek??c.weekStart,days=[0,1,2,3,4,5,6].map(k=>dAdd(ws,k)),we=days[6],live=items.filter(i=>i.schedulable);
 const inWeek=items.filter(i=>i.neededOn&&i.neededOn>=ws&&i.neededOn<=we),over=ws>=c.weekStart?live.filter(i=>i.neededOn&&i.neededOn<ws&&i.neededOn<c.today).sort(schByDate):[],undated=live.filter(i=>!i.neededOn).sort(schSort);
 const known=new Map(state.trucks.map(t=>[t.id,t])),rowIds=ops?schTrucks().map(t=>t.id):[],runName=new Map();for(const i of items)if(i.runTruck){if(!runName.has(i.runTruck))runName.set(i.runTruck,i.runTruckName??name(i.runTruck));if(!rowIds.includes(i.runTruck))rowIds.push(i.runTruck);}
