 const strip=(cls,title,sub,list,opts)=>'<section class="panel sch-strip '+cls+'"><div class="sch-strip-head"><h2>'+title+' <span class="sch-count">'+list.length+'</span></h2><p>'+sub+'</p></div><div class="sch-strip-cards">'+list.map(i=>schCard(i,opts.ctx,opts)).join('')+'</div></section>';
 const overHTML=over.length?strip('overdue','Overdue from earlier weeks','Needed before this week and still at the yard. Move each one to a new day.',over,{ctx:'over',truck:true}):'',undatedHTML=undated.length?strip('undated','No date yet','Give each one the day it is needed.',undated,{ctx:'undated',truck:true,setDate:true}):'';
 if(!inWeek.length&&!over.length&&!undated.length)return '<div class="page-schedule">'+schHero(items)+week+'<section class="panel sch-emptyweek"><span class="sch-empty-art">'+trkPic('spr-truck12')+'</span><h2>Nothing planned this week.</h2><p>'+(live.length?'Other weeks have loads booked. Use Previous and Next week to find them.':'Yard lists show here on the day they are needed, on the truck that runs them.')+'</p>'+(account.permissions.includes('requests.create')?'<button type="button" data-view="SITES" data-sch-create>Create a yard list</button>':'')+'</section></div>';
 const head=d=>{const [,m,x]=dYMD(d),wd=dWeekday(d);return '<div class="sch-dayhead'+(d===c.today?' today':'')+(wd>4?' weekend':'')+'"><b>'+SCH_DAYS[wd]+'</b><span>'+x+' '+SCH_MONTHS[m-1]+'</span>'+(d===c.today?'<em>Today</em>':'')+'</div>';};
 const cell=(match,d,cls='')=>{const list=inWeek.filter(i=>i.neededOn===d&&match(i)).sort(schSort),clash=list.length>1&&new Set(list.map(i=>i.site)).size>1&&list.some(i=>i.clash>0);return '<div class="sch-cell'+cls+(d===c.today?' today':'')+(dWeekday(d)>4?' weekend':'')+(clash?' clash':'')+'">'+(list.length?list.map(i=>schCard(i,'grid')).join(''):'<span class="sch-dot" aria-hidden="true">&middot;</span>')+'</div>';};
