 document.querySelectorAll('[data-sch-create]').forEach(b=>b.onclick=()=>{if(!schGo('SITES'))return;const d=document.getElementById('load-list-panel');if(d){d.open=true;d.scrollIntoView({block:'start'});}});
 const week=d=>{const c=cal();if(!c)return;const next=dAdd(schedWeek??c.weekStart,d);schedWeek=next===c.weekStart?null:next;schedX=null;render();};
 setOn(document.querySelector('#sch-prev'),'click',()=>week(-7));setOn(document.querySelector('#sch-next'),'click',()=>week(7));setOn(document.querySelector('#sch-today'),'click',()=>{schedWeek=null;schedX=null;render();});
 document.querySelectorAll('[data-set-date]').forEach(b=>b.onclick=()=>{const i=b.closest('form')?.querySelector('input[name="neededOn"]');if(i){i.value=b.dataset.setDate;i.dispatchEvent(new Event('input',{bubbles:true}));}});
 if(view==='SCHEDULE'&&schedOpen.size)onRenderKey(e=>{if(e.key!=='Escape'||e.target?.matches?.('input,select,textarea'))return;schedOpen.clear();render();});
