const spotText=p=>p.support?'onto '+esc(name(p.support)):(p.x/1000).toFixed(1)+', '+(p.y/1000).toFixed(1)+' m';
function plannerPanel(yard){const moves=Object.entries(layoutDraft.moves),check=layoutCheck;return '<section class="worker-command-panel planner-panel"><div class="row"><div><div class="eyebrow">LAYOUT PLANNER</div><h2>'+moves.length+' move'+(moves.length===1?'':'s')+' planned</h2></div><button type="button" class="secondary" id="planner-exit">Exit planner</button></div><p>Drag a stillage to where it should go. Drop it onto another stillage to stack it there. Whole piles move together. Nothing changes in the yard until you commit the plan; then the crew gets the instructions one by one.</p>'+(selected&&plannedContainers().some(c=>c.id===selected&&c.location===yard.id)?'<div class="planner-selected">Selected: '+esc(name(selected))+' <button type="button" class="secondary" id="planner-turn">&#10227; Turn selected (R)</button></div>':'')+(moves.length?'<ul class="planner-moves">'+moves.map(([id,m])=>{const c=state.containers.find(c=>c.id===id);return '<li><strong>'+esc(c?.name??id)+'</strong> \u2192 '+spotText(m)+(c&&m.rotation!==c.rotation?' \u00b7 turned':'')+' <button type="button" class="text-button" data-unplan="'+id+'">undo</button></li>';}).join('')+'</ul>':'<p class="muted">No moves yet. Drag a stillage on the plan above.</p>')+(check?'<div class="planner-check '+(check.ok?'ok':'bad')+'">'+(check.ok?'<strong>'+check.steps.length+' instruction'+(check.steps.length===1?'':'s')+' for the crew</strong><ol>'+check.steps.map(s=>'<li>'+esc(s.name)+(s.park?' \u2192 set down for now at ':' \u2192 ')+spotText(s.to)+'</li>').join('')+'</ol>'+(check.warnings?.length?'<p class="error-text">'+check.warnings.map(esc).join(' ')+'</p>':''):'<span class="error-text">'+esc(check.message)+'</span>')+'</div>':'')+'<div class="worker-buttons"><button type="button" class="secondary" id="planner-check" '+(moves.length?'':'disabled')+'>Check plan</button><button type="button" id="planner-commit" '+(moves.length?'':'disabled')+'>Commit this plan</button><button type="button" class="secondary" id="planner-clear" '+(moves.length?'':'disabled')+'>Clear</button></div></section>';}
function layoutsPanel(){const list=(state.layouts??[]).filter(l=>l.status==='ACTIVE');if(!list.length)return '';return list.map(l=>'<section class="panel layout-progress"><div class="row"><h2>'+esc(l.name)+(l.purpose==='TURN'?' <span class="badge turn">PILE TURN</span>':'')+'</h2><span class="badge '+(l.done===l.steps.length?'available':'busy')+'">'+l.done+' of '+l.steps.length+' done</span></div><p>Instructions the crew is working through, in order.</p><ol>'+l.steps.map(s=>'<li class="'+esc(s.state)+'"><strong>'+esc(s.name)+'</strong> '+(s.park?'set down for now at ':'\u2192 ')+spotText(s.to)+' <span class="badge '+(s.state==='COMPLETE'?'available':'')+'">'+esc(s.state.replaceAll('_',' '))+'</span>'+(s.reason?'<br><span class="error-text">'+esc(s.reason)+'</span>':'')+'</li>').join('')+'</ol>'+(account.permissions.includes('operations.manage')?'<div class="actions"><button type="button" class="secondary" data-cancel-layout="'+l.id+'">Cancel remaining steps</button></div>':'')+'</section>').join('');}
function bindPlanner(svg,yard){
 const planned=plannedContainers().filter(c=>c.location===yard.id),byId=new Map(planned.map(c=>[c.id,c]));
 const foot=(c,p)=>({x:p.x,y:p.y,w:p.rotation===90?c.envelopeWidth:c.envelopeLength,h:p.rotation===90?c.envelopeLength:c.envelopeWidth});
 const zones=[{...yard.loading,w:2000,h:1500,name:'loading zone'},...(yard.fixtures??[])];
 const frame=planFrame(yard,planView),k=planView.tilt?0.9:0.22,upUnit={x:-frame.inverse[2],y:-frame.inverse[3]},up=h=>({x:upUnit.x*h*k,y:upUnit.y*h*k});
 const level=id=>{let n=1,cur=byId.get(id),g=0;while(cur?.support&&g++<9){n++;cur=byId.get(cur.support);}return n;};
 const heightBelow=id=>{let h=0,cur=byId.get(id),g=0;while(cur&&g++<9){h+=cur.height;cur=byId.get(cur.support);}return h;};
 let drag=null,last=null;
 const ghost=()=>{svg.querySelector('#layout-ghost')?.remove();if(!drag?.cand)return;const c=byId.get(drag.id),cand=drag.cand,r=foot(c,cand),color=cand.valid?'#36852e':'#bd4636';const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='layout-ghost';g.setAttribute('pointer-events','none');g.innerHTML='<rect x="'+r.x+'" y="'+r.y+'" width="'+r.w+'" height="'+r.h+'" fill="'+color+'" fill-opacity=".35" stroke="'+color+'" stroke-width="70" stroke-dasharray="200 120"/><text x="'+(r.x+r.w/2)+'" y="'+(r.y-200)+'" text-anchor="middle" font-size="260" font-weight="700" fill="'+color+'" stroke="#f8ffeb" stroke-width="14" paint-order="stroke">'+esc(c.name)+(drag.pile.length>1?' +'+(drag.pile.length-1):'')+(cand.support?' onto '+esc(byId.get(cand.support).name):'')+(cand.valid?'':' \u2715')+'</text>';(svg.querySelector('#plan')??svg).append(g);};
 const candidate=pt=>{const c=byId.get(drag.id),pile=drag.pile,pileHeight=pile.reduce((s,id)=>s+byId.get(id).height,0);
  const target=planned.filter(t=>!pile.includes(t.id)&&t.type===c.type&&!planned.some(o=>o.support===t.id)).map(t=>{const r=foot(t,t),lift=up(heightBelow(t.id));return {t,r,top:{x:r.x+lift.x,y:r.y+lift.y,w:r.w,h:r.h}};}).filter(({top})=>pt.x>=top.x&&pt.x<=top.x+top.w&&pt.y>=top.y&&pt.y<=top.y+top.h).sort((a,b)=>level(b.t.id)-level(a.t.id))[0];
  if(target){const t=target.t,r=foot(c,{x:t.x,y:t.y,rotation:t.rotation});const tooHigh=level(t.id)+pile.length>7,tooTall=heightBelow(t.id)+pileHeight>(yard.height??10000),ok=!tooHigh&&!tooTall&&containsRect(target.r,r);return {x:t.x,y:t.y,rotation:t.rotation,support:t.id,valid:ok,reason:ok?'':tooHigh?'That pile would be more than 7 high.':tooTall?'That pile would be taller than the yard storage height.':c.name+' does not fit on '+t.name+'.'};}
  const w=drag.rotation===90?c.envelopeWidth:c.envelopeLength,h=drag.rotation===90?c.envelopeLength:c.envelopeWidth,x=Math.round((pt.x-w/2)/500)*500,y=Math.round((pt.y-h/2)/500)*500,r={x,y,w,h};
  const inside=fitsPolygon(r,yard.points),zone=zones.find(z=>overlap(r,z)),hit=planned.find(o=>!pile.includes(o.id)&&!o.support&&overlap(r,foot(o,o)));
  return {x,y,rotation:drag.rotation,support:null,valid:inside&&!zone&&!hit,reason:!inside?'Keep the stillage inside the yard boundary.':zone?'Keep the '+zone.name.toLowerCase()+' clear.':hit?'That spot overlaps '+hit.name+'. Drop onto it to stack instead.':''};};
 svg.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-select]');if(e.button!==0||!el||!byId.has(el.dataset.select))return;const c=byId.get(el.dataset.select);last=planPoint(svg,e);drag={id:c.id,pile:pileAbove(c.id,planned),rotation:c.rotation,start:last,moved:false,cand:null};planDragging=true;try{svg.setPointerCapture(e.pointerId);}catch{}},true);
 svg.addEventListener('pointermove',e=>{if(!drag)return;last=planPoint(svg,e);if(!drag.moved&&Math.hypot(last.x-drag.start.x,last.y-drag.start.y)<250)return;drag.moved=true;svg.style.cursor='grabbing';drag.cand=candidate(last);ghost();});
 const finish=()=>{if(!drag)return;const d=drag;drag=null;planDragging=false;svg.style.cursor='';svg.querySelector('#layout-ghost')?.remove();if(!d.moved){if(selected!==d.id){selected=d.id;setTimeout(render,0);}return;}suppressPlanClick=true;setTimeout(()=>{suppressPlanClick=false;},300);if(!d.cand?.valid){notify(d.cand?.reason||'That spot is not clear. Choose open ground inside the yard.');return;}for(const id of d.pile){const c=byId.get(id),orig=state.containers.find(o=>o.id===id),m={x:d.cand.x,y:d.cand.y,rotation:d.cand.rotation,support:id===d.id?d.cand.support:c.support};if(m.x===orig.x&&m.y===orig.y&&m.rotation===orig.rotation&&(m.support??null)===(orig.support??null))delete layoutDraft.moves[id];else layoutDraft.moves[id]=m;}layoutCheck=null;setTimeout(render,0);};
 svg.addEventListener('pointerup',finish);svg.addEventListener('pointercancel',finish);
 onRenderKey(e=>{if(e.target?.matches?.('input,select,textarea'))return;if(!drag){if(e.key?.toLowerCase()==='r'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.repeat&&selected&&byId.has(selected)){e.preventDefault();draftTurn(selected);}return;}if(e.key.toLowerCase()==='r'){e.preventDefault();drag.rotation=drag.rotation===0?90:0;if(drag.moved&&last){drag.cand=candidate(last);ghost();}}if(e.key==='Escape'){drag=null;planDragging=false;svg.style.cursor='';svg.querySelector('#layout-ghost')?.remove();}});
}


export const __test={setState(s,a){state=s;account=a;},wire({api:a,notify:n,live:l=true}={}){if(a)api=a;if(n)notify=n;live=l;},turnKey:c=>turnKey(c),turnNow:id=>turnNow(id),turnInfo:id=>turnInfo.get(id),refresh:force=>refresh(force),containerPage:v=>{if(v!==undefined)containerPage=v;return containerPage;},pager:()=>pagerHTML(),addRenderKey:fn=>onRenderKey(fn),renderKeyCount:()=>renderKeys.length,keyHandlerCount:()=>keyHandlers.size,dispatchKey:e=>dispatchKey(e),setApp(a){app=a;},workersView:()=>workersView(),setView(v){view=v;},homeView:()=>homeView(),sgCard:()=>sgCard(),detail:()=>detail(),setSelected(id){selected=id;},setLayoutDraft(d){layoutDraft=d;},setShapeEditor(e){shapeEditor=e;},editorHTML:()=>view==='SITES'?siteView():view==='HOME'?homeView():yardView(),setTurnInfo(id,plan,key='test'){if(plan===null)turnInfo.delete(id);else turnInfo.set(id,{key,plan});},setTurnBusy(id,on=true){if(on)turnBusy.add(id);else turnBusy.delete(id);},yardView:()=>yardView(),siteView:()=>siteView(),selectionBar:loc=>selectionBar(loc),whereLine:c=>whereLine(c),activityPanel:()=>activityPanel(),layoutsPanel:()=>layoutsPanel(),projectionMap:(s,plan)=>projectionMap(s,plan),changedKeys:(a,b)=>changedKeys(a,b),catalogue:()=>catalogue,state:()=>state,pollDelay:()=>pollDelay(),stockpile:()=>stockpilePanel(),setStep(n){step=n;},setGridSearch(g){gridSearch=g;},setAccount(a){account=a;},scheduleView:()=>scheduleView(),schedWeek:v=>{if(v!==undefined)schedWeek=v;return schedWeek;},schedOpen:()=>schedOpen,requestView:()=>requestView(),truckView:m=>truckView(m),overviewView:()=>overviewView(),homeDue:()=>homeDue()};
